// Data shapes for empty-state rendering and tests: what the TUI sees before the first scan, and
// what the live source can provide today (sessions, tokens, skills; no money, limits, router,
// workflows or search). Dev and test only.
import type { Item, TuiData } from "../src/model";

const md = (name: string, steps: string[]): string[] => [
  "---",
  `name: ${name}`,
  'description: "Generated by Reflex from repeated sessions."',
  "metadata:",
  "  generator: reflex",
  '  created: "2026-10-10"',
  "---",
  "",
  `# ${name}`,
  "",
  "## Workflow",
  "",
  ...steps.map((s, i) => `${i + 1}. ${s}`),
];

const item = (name: string, on: boolean, support: number, updated: string, state: Item["state"], steps: string[]): Item => ({
  name,
  on,
  support,
  updated,
  state,
  steps: steps.length,
  path: `~/.claude/skills/${name}/SKILL.md`,
  markdown: md(name, steps),
});

/** Before the first scan: nothing measured, nothing generated. */
export function emptyData(): TuiData {
  return {
    sessions: 0,
    dataDir: "~/.reflex",
    reads: [],
    activeDirs: ["~/.claude/skills", "~/.codex/skills"],
    tools: [],
    skills: { items: [], targets: ["~/.claude/skills/<name>/SKILL.md", "~/.codex/skills/<name>/SKILL.md"] },
    attention: [],
  };
}

/** What the live source provides in this release. */
export function liveShapeData(): TuiData {
  const labels = ["04 Oct", "05 Oct", "06 Oct", "07 Oct", "08 Oct", "09 Oct", "10 Oct"];
  const tokens = [21.4e6, 8.2e6, 31.9e6, 44.1e6, 38.7e6, 27.3e6, 35.0e6];
  return {
    scannedAt: "08:02",
    sessions: 312,
    dataDir: "~/.reflex",
    reads: ["~/.claude/projects", "~/.codex/sessions", "~/.cursor/projects"],
    activeDirs: ["~/.claude/skills", "~/.codex/skills", "~/.cursor/skills"],
    days: labels.map((label, i) => ({ label, tokens: tokens[i]! })),
    yesterday: { label: "sat 10 oct", sessions: 41, contextTokens: 34.1e6, outputTokens: 0.9e6 },
    window: { days: 7, range: "04 oct – 10 oct", sessions: 312, tokens: { input: 9.6e6, cacheWrite: 14.2e6, cacheRead: 179.8e6, output: 2.9e6 } },
    tools: [
      { tool: "claude", sessions: 201 },
      { tool: "codex", sessions: 88 },
      { tool: "cursor", sessions: 23 },
    ],
    skills: {
      items: [
        item("fix-ci", true, 9, "08 Oct", "", ["Inspect the failing CI run", "Reproduce the failure locally", "Patch the root cause", "Run the tests again"]),
        item("review-pr", false, 6, "10 Oct", "new", ["Read the diff", "Run the tests", "Write review comments"]),
        item("debug-dependency", false, 4, "10 Oct", "new", ["Inspect the lockfile", "Reinstall dependencies", "Run the build"]),
        item("bump-node-version", true, 3, "02 Oct", "retired", ["Update .nvmrc", "Update CI images", "Run the tests"]),
        item("release-checklist", true, 5, "05 Oct", "", ["Update the changelog", "Tag the release", "Verify the published package"]),
        item("flaky-test-triage", false, 7, "09 Oct", "", ["Run the test alone", "Bisect test order", "Fix the shared state"]),
      ],
      targets: ["~/.claude/skills/<name>/SKILL.md", "~/.codex/skills/<name>/SKILL.md", "~/.cursor/skills/<name>/SKILL.md"],
    },
    attention: [
      { tone: "ok", text: "2 new skills to review", view: "skills" },
      { tone: "bad", text: "1 retired skill is still installed", view: "skills" },
    ],
  };
}
